from PIL import Image
import glob, os

def blobs(path, vmin=90, vmax=145, max_spread=20):
    im = Image.open(path)
    w,h = im.size
    px = im.load()
    mask = [[False]*w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            r,g,b = px[x,y][:3]
            if vmin <= r <= vmax and abs(r-g)<=12 and abs(g-b)<=12 and r < 140:
                # exclude near-black gripper
                mask[y][x] = True
    visited = [[False]*w for _ in range(h)]
    found = []
    for y in range(h):
        for x in range(w):
            if not mask[y][x] or visited[y][x]:
                continue
            # flood
            stack = [(x,y)]
            visited[y][x] = True
            pts = []
            while stack:
                cx,cy = stack.pop()
                pts.append((cx,cy))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny = cx+dx, cy+dy
                    if 0<=nx<w and 0<=ny<h and mask[ny][nx] and not visited[ny][nx]:
                        visited[ny][nx] = True
                        stack.append((nx,ny))
            if len(pts) < 8 or len(pts) > 5000:
                continue
            xs = [p[0] for p in pts]; ys = [p[1] for p in pts]
            cx = sum(xs)/len(xs); cy = sum(ys)/len(ys)
            bw = max(xs)-min(xs); bh = max(ys)-min(ys)
            # circle-ish
            if bw > 80 or bh > 80:
                continue
            found.append((len(pts), cx, cy, bw, bh))
    found.sort(key=lambda t: -t[0])
    return found

for p in sorted(glob.glob("/home/robot/captures/wrist_00*.png")):
    print(os.path.basename(p), blobs(p)[:8])
