from PIL import Image

def find_dark(path, vmin=20, vmax=80):
    im = Image.open(path)
    w,h = im.size
    px = im.load()
    # find non-gripper dark objects: connected components of mid-dark not touching the big gripper
    mask=[[False]*w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            r,g,b=px[x,y][:3]
            v=(r+g+b)/3
            if vmin<=v<=vmax and abs(r-g)<15 and abs(r-b)<20:
                mask[y][x]=True
    vis=[[False]*w for _ in range(h)]
    blobs=[]
    for y in range(h):
        for x in range(w):
            if not mask[y][x] or vis[y][x]:
                continue
            st=[(x,y)]; vis[y][x]=True; pts=[]
            while st:
                cx,cy=st.pop(); pts.append((cx,cy))
                for dx in (-1,0,1):
                    for dy in (-1,0,1):
                        if dx==0 and dy==0: continue
                        nx,ny=cx+dx,cy+dy
                        if 0<=nx<w and 0<=ny<h and mask[ny][nx] and not vis[ny][nx]:
                            vis[ny][nx]=True; st.append((nx,ny))
            if 15 < len(pts) < 8000:
                xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
                blobs.append((len(pts), sum(xs)/len(xs), sum(ys)/len(ys), min(xs), max(xs), min(ys), max(ys)))
    blobs.sort(key=lambda t:-t[0])
    return blobs[:8]

for pos in [(300, 200, 120), (300, 230, 110), (330, 200, 110)]:
    print("MOVE", workcell.robot("move", *pos).text)
    path = workcell.robot("camera", "wrist").text.split()[-1]
